def max_N1(k, n):
    # N1[i][j] is max N1 for 2^i with j cells
    # i from 0 to k, j from 2 to n
    N1 = [[0] * (n + 1) for _ in range(k + 1)]

    for j in range(2, n + 1):
        N1[0][j] = 1

    for i in range(1, k + 1):
        N1[i][2] = i + 1
        for j in range(3, n + 1):
            N1[i][j] = N1[i-1][j] + N1[i-1][j-1]

    return N1[k][n]

print(max_N1(40, 9))

def max_M(k, n):
    # N1[i][j] is max N1 for 2^i with j cells
    N1 = [[0] * (n + 1) for _ in range(k + 1)]

    for j in range(1, n + 1):
        N1[0][j] = 1

    for i in range(1, k + 1):
        for j in range(1, n + 1):
            if j == 1:
                if i == 0:
                    N1[i][j] = 1
                else:
                    N1[i][j] = 0 # Impossible to get 2^i with 1 cell unless i=0
            elif j == 2:
                N1[i][j] = i + 1
            else:
                # This is the part to be careful about.
                # To get 2^i with j cells, we get one 2^{i-1} using j cells,
                # then we get another 2^{i-1} using j-1 cells.
                # But we already have one 2^{i-1} in one cell.
                # So we only have j-1 cells left to use.
                N1[i][j] = N1[i-1][j] + N1[i-1][j-1]

    return 2 * N1[k][n] - 1

print(max_M(40, 9))

def max_N1(k, n):
    N1 = [[0] * (n + 1) for _ in range(k + 1)]
    for j in range(1, n + 1):
        N1[0][j] = 1
    for i in range(1, k + 1):
        N1[i][1] = 0
        N1[i][2] = i + 1
        for j in range(3, n + 1):
            N1[i][j] = N1[i-1][j] + N1[i-1][j-1]
    return N1[k][n]

print(max_N1(40, 9))

def max_M_new(k, n):
    M = [[0] * (n + 1) for _ in range(k + 1)]
    for j in range(1, n + 1):
        M[0][j] = 1
    for i in range(1, k + 1):
        M[i][1] = 1
        for j in range(2, n + 1):
            M[i][j] = M[i-1][j] + M[i-1][j-1] + 1
    return M[k][n]

print(max_M_new(40, 9))

